"""Summarize CSV text with columns name and amount."""
import csv
import io

def summarize(text):
    count = 0
    total = 0.0
    for row in csv.DictReader(io.StringIO(text)):
        if not any(str(value or "").strip() for value in row.values()):
            continue
        count += 1
        total += float(row["amount"])
    return {"count": count, "total": total}
